"""Snap span edges to a fixed step and label the results."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def check_step(step: int) -> None:
    """Raise ValueError unless step divides an hour."""
    if not isinstance(step, int) or step <= 0:
        raise ValueError(f"bad step: {step!r}")
    if 60 % step:
        raise ValueError(f"bad step: {step}")


def snap_minutes(value: int, step: int) -> int:
    """Nearest multiple of step. Halfway points round up."""
    return (2 * value + step) // (2 * step) * step


def round_span(span: Span, step: int) -> Span:
    """Snap both edges. ValueError if the span collapses."""
    check_step(step)
    return Span(
        snap_minutes(span.start, step),
        snap_minutes(span.end, step)
    )


def label_span(span: Span) -> str:
    """Label such as 09:00-17:15 (8h 15m)."""
    hours, minutes = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {minutes}m)"


def round_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Round each span to step and give back its label."""
    check_step(step)
    return [
        label_span(round_span(span, step)) for span in spans
    ]

