# owner: platform
import unittest

from hourglass.rounding import round_labels, round_span
from hourglass.parsing import parse_span
from hourglass.models import Span


class RoundLabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:00-17:15")]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_snaps_to_nearest(self):
        spans = [parse_span("08:53-17:07")]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:00 (8h 0m)"]
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            round_span(Span(15, 45), 30), Span(30, 60)
        )

    def test_rounds_to_end_of_day(self):
        self.assertEqual(
            round_span(Span(1400, 1438), 30),
            Span(1410, 1440)
        )

    def test_several_spans_and_empty(self):
        spans = [Span(0, 62), Span(100, 190)]
        self.assertEqual(
            round_labels(spans, 30),
            ["00:00-01:00 (1h 0m)", "01:30-03:00 (1h 30m)"]
        )
        self.assertEqual(round_labels([], 30), [])

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_labels([Span(61, 70)], 30)


class BadStepTests(unittest.TestCase):
    def test_zero_negative_and_uneven_steps(self):
        spans = [Span(60, 120)]
        for step in (0, -15, 7, 25, 90, 120):
            with self.assertRaises(ValueError):
                round_labels(spans, step)

    def test_bad_step_raises_even_without_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_every_divisor_of_an_hour_is_accepted(self):
        steps = (1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60)
        for step in steps:
            self.assertEqual(
                round_labels([Span(0, 120)], step),
                ["00:00-02:00 (2h 0m)"]
            )


if __name__ == "__main__":
    unittest.main()
